code.cpp:
class Solution {
public:
    vector<int> findBall(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        vector<int> answer(n);
        for (int ball = 0; ball < n; ball++) {
            int col = ball;
            bool stuck = false;
            for (int row = 0; row < m; row++) {
                if (grid[row][col] == 1) {
                    if (col + 1 >= n || grid[row][col + 1] == -1) {
                        stuck = true;
                        break;
                    }
                    col++;
                } else {
                    if (col - 1 < 0 || grid[row][col - 1] == 1) {
                        stuck = true;
                        break;
                    }
                    col--;
                }
            }
            answer[ball] = stuck ? -1 : col;
        }
        return answer;
    }
};
